/// <summary>
/// CB167_PerformStockReservation
/// This is a service class for reserve event orders batch job.
/// </summary>
class METReserveEventOrdersService extends METSysOperationService
{
    private METReserveEventOrdersContract contract;
    private guid topPickingProcessId;
    private Set salesIdSet;

}

Method.Source:
// <summary>
/// Returns task service class name.
/// </summary>
/// <returns>Task service class name</returns>
protected str getTaskServiceClass()
{
    return classStr(METReserveEventOrdersTaskService);
}

/// <summary>
/// Returns task service class method.
/// </summary>
/// <returns>Task service class method</returns>
protected str getTaskServiceClassMethod()
{
    return methodStr(METReserveEventOrdersTaskService, process);
}

/// <summary>
/// Returns caption of the task service class.
/// </summary>
/// <returns>Task service class caption</returns>
protected str getTaskServiceCaption()
{
    return "@MET:METReserveEventOrders";
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METReserveEventOrdersContract</c>
/// </param>
public void process(METReserveEventOrdersContract _contract)
{
    this.processInternal(_contract);

    // Bug 281545: CB515 - Not sending for repricing on Extraction
    // After all threads are completed, update the order processing status to ready for pricing
    if (salesIdSet && salesIdSet.elements() > 0)
    {
        SetEnumerator se = salesIdSet.getEnumerator();

        while (se.moveNext())
        {
            SalesId salesId = se.current();

            SalesTable salesTable = SalesTable::find(salesId);
            METSalesTable metSalesTable = salesTable.metSalesTable();
            ttsbegin;
            metSalesTable.selectForUpdate(true);
            metSalesTable.OrderProcessingStatus = METSalesOrderProcessingStatus::ReadyForPricing;
            metSalesTable.update();
            ttscommit;
        }
    }
}

/// <summary>
/// Initialise global variables.
/// </summary>
public void initialise()
{        
    super();

    salesIdSet = this.stageDataIntoQueue();
}

/// <summary>
/// Stages data int table <c>METReserveEventOrdersQueue</c>.
/// </summary>
Set stageDataIntoQueue()
{
    #OCCRetryCount
    Set ret;

    contract            = dataContract as METReserveEventOrdersContract;
    topPickingProcessId = newGuid();

    try
    {
        ttsbegin;

        METReserveEventOrdersQueue::cleanUpReserveEventOrdersQueue();
        ret = this.stageEventOrders();

        ttscommit;

    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Error)
    {
        // catch the errors so processing can continue
        curext(); // avoids a warning about an empty block
    }

    return ret;
}

/// <summary>
/// Stages event orders.
/// </summary>
private Set stageEventOrders()
{
    METReserveEventOrdersTmp   eventOrdersTmp;
    METReserveEventOrdersQueue eventOrdersQueue;
    Query                      query;
    Set                        ret;

    query = contract.initQuery();
    /*
    Populates value in temp table.
    Query::insert_recordset by default doesn't support insert operation involving constants.
    Temp table is used to store values from the query.
    */
    eventOrdersTmp = METReserveEventOrdersTmp::populateTmp(query);

    insert_recordset eventOrdersQueue(ProcessId, SalesLineTransId, POLink)
    select topPickingProcessId, SalesLineTransId, POLink from eventOrdersTmp;     

    // Bug 281545: CB515 - Not sending for repricing on Extraction
    // Get the SalesId for the query used to populate the queue so we can update the order processing status to ready for pricing at the end
    ret = this.initSalesIdset(eventOrdersTmp);

    return ret;
}

/// <summary>
/// Initializes the task data contract.
/// </summary>
/// <param name = "_taskDataContract">task data contract</param>
protected void initTaskDataContract(METSysOperationTaskDataContract _taskDataContract)
{
    super(_taskDataContract);
    contract = _taskDataContract as METReserveEventOrdersContract;

    contract.parmTopPickingProcessId(topPickingProcessId);
}

/// <summary>
/// Provides task data contract.
/// </summary>
/// <returns>task data contract</returns>
protected METSysOperationTaskDataContract taskDataContractObject()
{
    return new METReserveEventOrdersContract();
}

/// <summary>
/// Initialises the salesId set from the temp table.
/// </summary>
/// <param name = "_eventOrdersTmp">Reserve event orders temp table</param>
/// <returns>Set of salesId</returns>
Set initSalesIdSet(METReserveEventOrdersTmp _eventOrdersTmp)
{
    SalesLine salesLine;
    Set ret = new Set(Types::String);

    while select _eventOrdersTmp
            join salesLine
        group by salesLine.SalesId
           where salesLine.InventTransId == _eventOrdersTmp.SalesLineTransId            
    {
        ret.add(salesLine.SalesId);
    }

    return ret;
}
